	    public void EncodeBase64NVARCHARFields(QuoteTemplateSettingPM entityPM)
        {
            if (String.IsNullOrWhiteSpace(entityPM.EncodeBase64NVARCHARFieldsBy)) 
            {
                return;
            }
            if (!String.IsNullOrWhiteSpace(entityPM.PageHeaderArea1FreeText)) //T4 find type == nText 
            {
                entityPM.PageHeaderArea1FreeText = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.PageHeaderArea1FreeText));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.PageHeaderArea2FreeText)) //T4 find type == nText 
            {
                entityPM.PageHeaderArea2FreeText = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.PageHeaderArea2FreeText));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.PageHeaderArea3FreeText)) //T4 find type == nText 
            {
                entityPM.PageHeaderArea3FreeText = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.PageHeaderArea3FreeText));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.PageFooterArea1FreeText)) //T4 find type == nText 
            {
                entityPM.PageFooterArea1FreeText = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.PageFooterArea1FreeText));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.PageFooterArea2FreeText)) //T4 find type == nText 
            {
                entityPM.PageFooterArea2FreeText = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.PageFooterArea2FreeText));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.PageFooterArea3FreeText)) //T4 find type == nText 
            {
                entityPM.PageFooterArea3FreeText = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.PageFooterArea3FreeText));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.XMLData)) //T4 find type == nText 
            {
                entityPM.XMLData = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.XMLData));
            }
            entityPM.EncodeBase64NVARCHARFieldsBy=null;
		}
